function validate([n, edges]) {
  if (!Number.isInteger(n) || n < 2 || n > 1000) return 'n is between 2 and 1000.';
  if (!Array.isArray(edges) || edges.length < 1 || edges.length > 1000) return 'edges needs 1 to 1000 entries.';
  const seen = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || v < 0 || u >= n || v >= n) return 'Edge endpoints are vertices from 0 to n - 1.';
    if (u === v) return 'An edge cannot join a vertex to itself.';
    const key = Math.min(u, v) * n + Math.max(u, v);
    if (seen.has(key)) return 'Each pair of vertices has at most one edge.';
    seen.add(key);
  }
  return null;
}

