function findShortestCycle(n, edges) {
  // The shortest cycle through edge (a, b) is 1 plus the shortest a-b path that avoids that edge.
  let shortest = -1;
  for (let skip = 0; skip < edges.length; skip++) {
    const [a, b] = edges[skip];
    const adj = Array.from({ length: n }, () => []);
    edges.forEach(([u, v], i) => { if (i !== skip) { adj[u].push(v); adj[v].push(u); } });
    const seen = new Array(n).fill(-1);
    seen[a] = 0;
    let frontier = [a];
    while (frontier.length && seen[b] === -1) {
      const following = [];
      for (const x of frontier) for (const y of adj[x]) if (seen[y] === -1) { seen[y] = seen[x] + 1; following.push(y); }
      frontier = following;
    }
    if (seen[b] !== -1 && (shortest === -1 || seen[b] + 1 < shortest)) shortest = seen[b] + 1;
  }
  return shortest;
}

