function generate(rand, size) {
  const shuffle = list => { for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; } return list; };
  const finish = (n, pairs) => {
    const label = shuffle(Array.from({ length: n }, (_, i) => i));
    return [n, shuffle(pairs.map(([u, v]) => rand() < 0.5 ? [label[u], label[v]] : [label[v], label[u]]))];
  };
  if (size === 'large') {
    const n = 1000;
    const mode = Math.floor(rand() * 3);
    if (mode === 0) {
      // A sparse random graph: 1000 distinct edges.
      const seen = new Set();
      const pairs = [];
      while (pairs.length < 1000) {
        const u = Math.floor(rand() * n);
        const v = Math.floor(rand() * n);
        const key = Math.min(u, v) * n + Math.max(u, v);
        if (u === v || seen.has(key)) continue;
        seen.add(key);
        pairs.push([u, v]);
      }
      return finish(n, pairs);
    }
    // A deep random tree, plus a few extra edges (mode 1) or none (mode 2).
    const k = mode === 1 ? 990 : n;
    const pairs = [];
    const seen = new Set();
    for (let i = 1; i < k; i++) {
      const p = Math.max(0, i - 1 - Math.floor(rand() * 3));
      pairs.push([p, i]);
      seen.add(p * n + i);
    }
    if (mode === 1) {
      const extra = 3 + Math.floor(rand() * 8);
      while (pairs.length < k - 1 + extra) {
        const u = Math.floor(rand() * k);
        const v = Math.floor(rand() * k);
        const key = Math.min(u, v) * n + Math.max(u, v);
        if (u === v || seen.has(key)) continue;
        seen.add(key);
        pairs.push([u, v]);
      }
    }
    return finish(n, pairs);
  }
  const n = 2 + Math.floor(rand() * 7);
  const density = [0.2, 0.35, 0.6][Math.floor(rand() * 3)];
  let pairs = [];
  for (let u = 0; u < n; u++) for (let v = u + 1; v < n; v++) if (rand() < density) pairs.push([u, v]);
  if (!pairs.length) pairs = [[0, 1]];
  return finish(n, pairs);
}
